import{_ as i,c as a,o as e,am as r}from"./chunks/framework.1_Rjriwz.js";const b=JSON.parse('{"title":"Vilinko Studio 隐私政策","description":"","frontmatter":{},"headers":[],"relativePath":"agreement/privacy.md","filePath":"agreement/privacy.md"}'),t={name:"agreement/privacy.md"};function o(u,l,h,n,d,s){return e(),a("div",null,l[0]||(l[0]=[r('<h1 id="vilinko-studio-隐私政策" tabindex="-1">Vilinko Studio 隐私政策 <a class="header-anchor" href="#vilinko-studio-隐私政策" aria-label="Permalink to &quot;Vilinko Studio 隐私政策&quot;">​</a></h1><p><a href="/en/agreement/privacy.html">【English Version】</a></p><div class="tip custom-block"><p class="custom-block-title">版本</p><p>初版发布日期：2025 年 8 月 6 日</p><p>最近更新日期：2025 年 8 月 6 日</p></div><h2 id="一、引言" tabindex="-1">一、引言 <a class="header-anchor" href="#一、引言" aria-label="Permalink to &quot;一、引言&quot;">​</a></h2><ul><li>欢迎使用 Vilinko Studio（以下简称“我们”）提供的互联网信息技术工具及相关服务。本隐私政策旨在向您说明我们如何收集、使用、存储、保护及披露您的个人信息，以及您享有的哪些与个人信息相关的权利。</li><li>本隐私政策与您使用我们的服务密切相关，请您在使用任何服务前仔细阅读并充分理解本政策，尤其是加粗或下划线标注的内容。您使用或继续使用我们的服务，即表示您同意我们按照本政策处理您的个人信息。</li><li>如对本政策有任何疑问，您可通过本政策提供的方式与我们取得联系。</li></ul><h2 id="二、适用范围" tabindex="-1">二、适用范围 <a class="header-anchor" href="#二、适用范围" aria-label="Permalink to &quot;二、适用范围&quot;">​</a></h2><ul><li>本政策适用于我们提供的所有服务，包括但不限于用户登录系统、论坛服务、个性化定制功能、电脑桌面美化工具、文件解释器等，以及相关的网站、客户端、小程序等。</li><li>本政策不适用于以下情况： <ul><li>第三方通过我们的服务向您提供的产品或服务，该等第三方服务可能有其独立的隐私政策，我们不对第三方的隐私政策及行为负责。</li><li>经我们授权的第三方服务，但该授权不包括对第三方收集、使用您个人信息的授权，第三方应根据其自身的隐私政策处理您的信息。</li></ul></li></ul><h2 id="三、我们收集的信息" tabindex="-1">三、我们收集的信息 <a class="header-anchor" href="#三、我们收集的信息" aria-label="Permalink to &quot;三、我们收集的信息&quot;">​</a></h2><h3 id="一-您主动提供的信息" tabindex="-1">（一）您主动提供的信息 <a class="header-anchor" href="#一-您主动提供的信息" aria-label="Permalink to &quot;（一）您主动提供的信息&quot;">​</a></h3><ul><li>注册信息：当您注册 Vilinko Studio 账号时，您可能需要提供手机号码、电子邮箱地址、用户名、密码等信息。若您选择通过第三方账号（如微信、QQ、GitHub 等）登录，我们会获取您在该第三方平台上已公开的信息（如昵称、头像等），具体以第三方授权页面显示的内容为准。</li><li>服务使用中提交的信息： <ul><li>在使用论坛服务时，您发布的帖子、评论、回复、私信等内容。</li><li>使用个性化定制功能时，您上传的图片、设置的偏好参数、输入的文字描述等。</li><li>通过客服系统、反馈渠道向我们提交的意见、建议、投诉及相关证明材料。</li></ul></li><li>其他主动提供的信息：如您参与我们的问卷调查、活动时提供的姓名、地址、联系方式等。</li></ul><h3 id="二-我们在您使用服务过程中收集的信息" tabindex="-1">（二）我们在您使用服务过程中收集的信息 <a class="header-anchor" href="#二-我们在您使用服务过程中收集的信息" aria-label="Permalink to &quot;（二）我们在您使用服务过程中收集的信息&quot;">​</a></h3><ul><li>设备信息：包括设备型号、操作系统类型及版本、设备标识符（如 IMEI、MEID、Android ID、IDFA、MAC 地址等）、设备硬件信息（如 CPU、内存、存储容量）、电池状态、传感器信息（如加速度传感器、陀螺仪）等。</li><li>网络信息：包括 IP 地址、网络类型（如 Wi-Fi、4G、5G）、网络运营商、接入点名称（APN）、蓝牙信息、Wi-Fi 热点信息等。</li><li>位置信息： <ul><li>若您同意使用涉及位置服务的功能（如基于位置的资源推荐），且您授权我们获取位置信息，我们可能通过 GPS、基站、Wi-Fi 等方式获取您的精确位置信息。</li><li>若您未授权，但服务功能需要大致位置信息，我们可能根据您的 IP 地址等信息获取您的大致地理位置。</li><li>您可随时通过设备系统设置或服务内的权限管理功能关闭位置信息授权，关闭后我们将不再收集，但可能影响相关功能的正常使用。</li></ul></li><li>日志信息： <ul><li>访问日志：包括您访问服务的时间、地点、访问的页面或功能、访问时长、点击记录等。</li><li>操作日志：包括您在服务中的操作行为（如登录、注销、修改设置、上传文件、下载资源等）、操作结果、错误信息等。</li><li>设备运行日志：包括服务在您设备上的运行状态、崩溃信息、异常日志等，用于排查故障、优化性能。</li></ul></li><li>文件信息： <ul><li>当您使用文件解释器功能时，我们会临时读取您选择的待解释文件内容，仅用于完成解释操作，操作结束后将根据设定清除临时数据（除非您选择保存结果）。</li><li>您通过服务上传、存储的文件（如个性化美化素材、论坛附件等），我们会按照您的设置进行存储和管理。</li></ul></li></ul><h3 id="三-从第三方获取的信息" tabindex="-1">（三）从第三方获取的信息 <a class="header-anchor" href="#三-从第三方获取的信息" aria-label="Permalink to &quot;（三）从第三方获取的信息&quot;">​</a></h3><ul><li>若您通过第三方合作平台使用我们的服务，或授权第三方向我们提供您的信息，我们会在符合法律法规及双方约定的前提下，获取您在该第三方平台的相关信息，具体以您与第三方的约定及授权范围为准。</li><li>为了保障服务安全、防范欺诈风险，我们可能从合法合规的第三方机构获取有关您的风险评估信息。</li></ul><h2 id="四、我们如何使用信息" tabindex="-1">四、我们如何使用信息 <a class="header-anchor" href="#四、我们如何使用信息" aria-label="Permalink to &quot;四、我们如何使用信息&quot;">​</a></h2><ul><li>向您提供服务：根据您的注册信息为您创建账号，保障您正常使用各项服务功能；基于您的操作指令处理相关请求（如解释文件、发布论坛内容）。</li><li>优化服务体验： <ul><li>根据设备信息和运行日志，优化服务在不同设备上的兼容性和稳定性，修复漏洞和故障。</li></ul></li><li>保障服务安全： <ul><li>利用设备信息、网络信息、日志信息等识别异常登录、恶意攻击等风险，采取安全措施保护您的账号和信息安全。</li><li>对违反法律法规或服务协议的行为进行监测和处理，维护服务秩序。</li></ul></li><li>沟通与通知： <ul><li>向您发送服务相关的通知（如账号注册成功通知、密码重置提醒、服务更新公告等）。</li><li>在获得您同意的情况下，向您推送活动信息等内容，您可通过相关设置取消接收。</li></ul></li><li>法律法规要求或保护合法权益： <ul><li>为遵守法律法规、响应司法机关或行政主管部门的合法要求，使用您的信息。</li><li>在合理必要范围内，为维护我们及用户的合法权益（如应对诉讼、仲裁），使用您的信息。</li></ul></li><li>其他经您同意的用途：如用于市场调研、产品改进等，我们会在使用前明确告知并获得您的同意。</li></ul><h2 id="五、信息的存储与保护" tabindex="-1">五、信息的存储与保护 <a class="header-anchor" href="#五、信息的存储与保护" aria-label="Permalink to &quot;五、信息的存储与保护&quot;">​</a></h2><h3 id="一-存储地点" tabindex="-1">（一）存储地点 <a class="header-anchor" href="#一-存储地点" aria-label="Permalink to &quot;（一）存储地点&quot;">​</a></h3><ul><li>您的个人信息存储在中华人民共和国境内的服务器。</li></ul><h3 id="二-存储期限" tabindex="-1">（二）存储期限 <a class="header-anchor" href="#二-存储期限" aria-label="Permalink to &quot;（二）存储期限&quot;">​</a></h3><ul><li>我们会根据信息的类型及使用目的，确定合理的存储期限： <ul><li>账号信息：在您的账号处于活跃状态期间，我们会持续存储；若您注销账号，我们将在合理期限内删除或匿名化处理。</li><li>法律法规另有规定的，按规定执行（如为履行法定职责或应对纠纷需要保留的信息，存储期限可能延长）。</li></ul></li></ul><h3 id="三-保护措施" tabindex="-1">（三）保护措施 <a class="header-anchor" href="#三-保护措施" aria-label="Permalink to &quot;（三）保护措施&quot;">​</a></h3><ul><li>采用加密技术（如 SSL/TLS 加密传输、数据加密存储）、访问控制机制、防火墙、入侵检测系统等技术手段，防止信息被未授权访问、泄露、篡改或损坏。</li><li>制定数据安全事件应急预案，如发生信息泄露等安全事件，将及时采取补救措施，并按照规定向有关部门报告及通知您。</li></ul><h2 id="六、信息的共享、转让与公开披露" tabindex="-1">六、信息的共享、转让与公开披露 <a class="header-anchor" href="#六、信息的共享、转让与公开披露" aria-label="Permalink to &quot;六、信息的共享、转让与公开披露&quot;">​</a></h2><h3 id="一-共享" tabindex="-1">（一）共享 <a class="header-anchor" href="#一-共享" aria-label="Permalink to &quot;（一）共享&quot;">​</a></h3><ul><li>我们不会向第三方共享您的个人信息，除非符合以下情况： <ul><li>获得您的明确同意：在共享前会明确告知您共享的目的、第三方身份及信息范围，经您确认同意后再进行共享。</li><li>服务必要：为向您提供服务，需与第三方服务提供商（如服务器托管商、云存储服务商、支付服务商等）共享必要信息，该等第三方仅能在提供服务的范围内使用信息，并需遵守保密义务。</li><li>法律法规要求：根据法律法规、司法机关或行政主管部门的强制性要求，向相关部门共享信息。</li><li>保护合法权益：在合理必要范围内，为保护我们及用户的合法权益（如防止欺诈、处理侵权行为），向相关方共享信息。</li></ul></li></ul><h3 id="二-转让" tabindex="-1">（二）转让 <a class="header-anchor" href="#二-转让" aria-label="Permalink to &quot;（二）转让&quot;">​</a></h3><ul><li>未经您的明确同意，我们不会将您的个人信息转让给任何第三方。如因企业合并、分立、收购、重组等原因需要转让的，我们会提前通知您，并确保受让方继续遵守本政策的规定；如您不同意，可选择注销账号。</li></ul><h3 id="三-公开披露" tabindex="-1">（三）公开披露 <a class="header-anchor" href="#三-公开披露" aria-label="Permalink to &quot;（三）公开披露&quot;">​</a></h3><ul><li>我们不会公开披露您的个人信息，除非符合以下情况： <ul><li>获得您的明确同意。</li><li>法律法规要求或有权机关指令。</li><li>为维护公共利益（如打击违法犯罪），在必要范围内公开披露。</li><li>您在服务中主动公开的信息（如论坛公开帖子），该等信息的公开范围以您的设置为准。</li></ul></li></ul><h2 id="七、您的权利" tabindex="-1">七、您的权利 <a class="header-anchor" href="#七、您的权利" aria-label="Permalink to &quot;七、您的权利&quot;">​</a></h2><ul><li>访问权：您有权访问您的个人信息（如账号基本信息、使用记录等）。</li><li>更正权：如您发现您的信息存在错误，可向我们提出更正申请，我们会在核实后及时更正。</li><li>删除权：在以下情况下，您可要求我们删除您的个人信息： <ul><li>我们收集、使用信息的目的已实现或不再必要。</li><li>您撤回了同意授权。</li><li>我们违反法律法规或协议约定处理您的信息。</li><li>其他依法可要求删除的情形。</li><li>我们会在核实后及时删除，如因法律法规规定需要保留的，我们会进行匿名化处理。</li></ul></li><li>撤回同意权：您可随时撤回对我们收集、使用信息的授权（如关闭权限设置），但撤回同意可能导致部分服务功能无法正常使用。</li><li>复制权：您可要求我们提供您的个人信息副本，我们会在符合规定的前提下以合理方式提供。</li><li>注销权：您可通过服务内的注销功能或联系客服注销您的账号，注销后我们将停止为您提供服务，并按规定处理您的信息（删除或匿名化）。</li><li>约束自动化决策权：对于通过自动化决策方式（如算法推荐）作出的对您权益有重大影响的决定，您有权要求我们作出解释，并可拒绝仅通过自动化决策的方式处理您的信息。</li></ul><h2 id="八、未成年人保护" tabindex="-1">八、未成年人保护 <a class="header-anchor" href="#八、未成年人保护" aria-label="Permalink to &quot;八、未成年人保护&quot;">​</a></h2><ul><li>我们高度重视未成年人的个人信息保护。若您是未满 18 周岁的未成年人，应在监护人的指导下使用我们的服务，并由监护人代为阅读本政策。</li><li>未成年人的监护人应妥善管理未成年人的账号及个人信息，如发现未成年人的信息被不当收集或使用，可联系我们处理。</li><li>我们不会向未成年人提供与年龄不适当的服务内容，也不会在未经监护人同意的情况下，向第三方披露未成年人的个人信息。</li></ul><h2 id="九、政策的更新与通知" tabindex="-1">九、政策的更新与通知 <a class="header-anchor" href="#九、政策的更新与通知" aria-label="Permalink to &quot;九、政策的更新与通知&quot;">​</a></h2><ul><li>我们可能会根据法律法规的变化、服务功能的调整等情况，对本隐私政策进行修订。</li><li>修订后的隐私政策将在我们的官方网站、服务客户端等显著位置公布，并注明生效日期。如修订内容涉及您的重大权益变更，我们会通过弹窗、短信、邮件等方式向您提示，并给予您合理的考虑期限。</li><li>您继续使用我们的服务，即表示您同意修订后的隐私政策；如您不同意，应停止使用服务。</li></ul><h2 id="十、联系我们" tabindex="-1">十、联系我们 <a class="header-anchor" href="#十、联系我们" aria-label="Permalink to &quot;十、联系我们&quot;">​</a></h2><ul><li>如您对本隐私政策有任何疑问、建议或投诉，可通过以下方式联系我们： <ul><li>邮箱：<a href="mailto:privacy@vilinko.com" target="_blank" rel="noreferrer">privacy@vilinko.com</a></li><li><a href="http://vilinkostudio.github.io/support" target="_blank" rel="noreferrer">Vilinko 反馈中心</a></li></ul></li></ul><h2 id="附录-第三方政策链接" tabindex="-1">附录：第三方政策链接 <a class="header-anchor" href="#附录-第三方政策链接" aria-label="Permalink to &quot;附录：第三方政策链接&quot;">​</a></h2><ul><li><a href="https://afdian.com/term" target="_blank" rel="noreferrer">爱发电平台服务条款</a></li></ul>',40)]))}const m=i(t,[["render",o]]);export{b as __pageData,m as default};
